# area: context_managers
# hypothesis: when __exit__ is annotated to return bool the with-block may swallow exceptions, so a name assigned only inside it is possibly unbound afterwards, whereas __exit__ returning None leaves it definitely bound.
from typing import reveal_type


class Swallow:
    def __enter__(self) -> int:
        return 1

    def __exit__(self, *args: object) -> bool:
        return True


class Keep:
    def __enter__(self) -> int:
        return 2

    def __exit__(self, *args: object) -> None:
        return None


def after_swallow() -> int:
    with Swallow() as n:
        value = n * 10
    return value  # expect-error: possibly unbound


def after_keep() -> int:
    with Keep() as n:
        value = n * 10
    return value


def swallowed() -> str:
    with Swallow():
        raise ValueError('dropped')
    return 'reached after swallow'


reveal_type(Swallow().__exit__)
print(after_keep(), swallowed())
print(after_swallow())
